-- Veterinaria (S15): script de la base en la nube (PostgreSQL: Neon o Supabase).
-- Equivale a script.sql (SQL Server). La base ya la crea el proveedor; ejecutar en su editor SQL.
-- ATENCIÓN: borra y vuelve a crear las tres tablas.

-- citext: texto que compara sin distinguir mayúsculas, como SQL Server por defecto
CREATE EXTENSION IF NOT EXISTS citext;

DROP TABLE IF EXISTS "Usuario";
DROP TABLE IF EXISTS "Cita";
DROP TABLE IF EXISTS "Mascota";

CREATE TABLE "Mascota" (
    "Id"              INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre"          CITEXT       NOT NULL CHECK (char_length("Nombre") <= 60),
    "Especie"         CITEXT       NOT NULL CHECK (char_length("Especie") <= 30),
    "Raza"            VARCHAR(60)  NULL,
    "FechaNacimiento" DATE         NULL,
    "NombreDueno"     CITEXT       NOT NULL CHECK (char_length("NombreDueno") <= 100),
    "Telefono"        VARCHAR(20)  NULL,
    "Activo"          BOOLEAN      NOT NULL DEFAULT TRUE
);

CREATE TABLE "Cita" (
    "Id"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MascotaId" INT           NOT NULL,
    "FechaHora" TIMESTAMP     NOT NULL,
    "Motivo"    VARCHAR(200)  NOT NULL,
    "Costo"     NUMERIC(10,2) NOT NULL DEFAULT 0,
    "Estado"    CITEXT        NOT NULL DEFAULT 'Pendiente',
    CONSTRAINT "FK_Cita_Mascota" FOREIGN KEY ("MascotaId") REFERENCES "Mascota"("Id"),
    CONSTRAINT "CK_Cita_Estado" CHECK ("Estado" IN ('Pendiente','Atendida','Cancelada'))
);

